private final CategoryRepository categoryRepository;
private final CategoryService categoryService;
private final BudgetService budgetService;
private final CategoryTrendService categoryTrendService;
private final ReadOnlyObjectProperty<YearMonth> selectedMonth;

private final ObservableList<BudgetService.CategoryTotal> rows = FXCollections.observableArrayList();
private final Label warningLabel = new Label();
private final ListView<Category> trendCategoryList = new ListView<>();
private final VBox trendDisplayBox = new VBox(4);
private List<CategoryTrendService.CategoryTrend> latestTrends = List.of();

public CategorySummaryView(CategoryRepository categoryRepository, CategoryService categoryService,
                            BudgetService budgetService, CategoryTrendService categoryTrendService,
                            ReadOnlyObjectProperty<YearMonth> selectedMonth) {
    this.categoryRepository = categoryRepository;
    this.categoryService = categoryService;
    this.budgetService = budgetService;
    this.categoryTrendService = categoryTrendService;
    this.selectedMonth = selectedMonth;
    warningLabel.setWrapText(true);
    trendCategoryList.getSelectionModel().setSelectionMode(SelectionMode.MULTIPLE);
    trendCategoryList.setPrefHeight(120);
    trendCategoryList.getSelectionModel().getSelectedItems().addListener(
            (ListChangeListener<Category>) change -> refreshTrendDisplay());
    refresh();
}

public Tab asTab() {
    Tab tab = new Tab("Categories", buildContent());
    tab.setClosable(false);
    return tab;
}

public void refresh() {
    List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(selectedMonth.get());
    rows.setAll(totals);
    long overBudgetCount = totals.stream().filter(BudgetService.CategoryTotal::isOverBudget).count();
    warningLabel.setText(overBudgetCount == 0
            ? "All categories are within target."
            : overBudgetCount + " categor" + (overBudgetCount == 1 ? "y is" : "ies are") + " over budget.");

    latestTrends = categoryTrendService.trendsThroughMonth(selectedMonth.get());
    trendCategoryList.getItems().setAll(latestTrends.stream().map(CategoryTrendService.CategoryTrend::getCategory).toList());
    refreshTrendDisplay();
}

private void refreshTrendDisplay() {
    List<Category> selected = trendCategoryList.getSelectionModel().getSelectedItems();
    List<Label> lines = latestTrends.stream()
            .filter(trend -> selected.contains(trend.getCategory()))
            .map(trend -> new Label(formatTrendLine(trend)))
            .toList();
    trendDisplayBox.getChildren().setAll(lines);
}

private String formatTrendLine(CategoryTrendService.CategoryTrend trend) {
    StringBuilder text = new StringBuilder(trend.getCategory().getName()).append(":  ");
    List<CategoryTrendService.MonthAmount> monthAmounts = trend.getMonthAmounts();
    for (int i = 0; i < monthAmounts.size(); i++) {
        CategoryTrendService.MonthAmount monthAmount = monthAmounts.get(i);
        if (i > 0) {
            text.append("  →  ");
        }
        text.append(monthAmount.month().getMonth().getDisplayName(TextStyle.SHORT, Locale.ROOT))
